'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process'),{parse,walk}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='1a5651a06fbb38600c3b453908b3bcbc832467fc',proofPath=path.join(root,'outils/audits/I18N-MEMBRES-ORGANISATIONS-871-preuve.json'),proof=fs.existsSync(proofPath)?JSON.parse(fs.readFileSync(proofPath)):null,code=f=>proof?execFileSync('git',['show',proof.codeCommit+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read(f),old=f=>execFileSync('git',['show',base+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6}),file='plateau-organisations-quetes.js';
const strip=n=>{if(!n||typeof n!=='object')return n;if(Array.isArray(n))return n.map(strip);return Object.fromEntries(Object.entries(n).filter(([k])=>!['start','end','loc','raw'].includes(k)).map(([k,v])=>[k,strip(v)]));};
test('membres : aucune autre fonction ni commande métier modifiée, mêmes droits et mêmes données',()=>{const before=parse(old(file)),after=parse(code(file));const fn=a=>a.body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='ouvrirGestionMembres');const a=fn(before),b=fn(after);assert.deepEqual(strip(a.body.body.slice(0,5)),strip(b.body.body.slice(0,5)));for(const tree of [before,after])tree.body=tree.body.filter(n=>n!==fn(tree));assert.deepEqual(strip(after),strip(before));for(const source of [old(file).slice(a.start,a.end),code(file).slice(b.start,b.end)]){assert.ok(source.includes('estChef && m.nom !== state.char?.name'));assert.ok(source.includes("m.nom === orga.chef ? ' 👑' : ''"));assert.ok(!/\b(?:await|fetch|sbRpc|saveState|deduireCoutOrdre)\b/.test(source));}assert.equal(execFileSync('git',['diff','--name-only',base,...(proof?[proof.codeCommit]:[]),'--','api','migrations','supabase','supabase.js','auth.js','data.js','forum.js','plateau-core.js','plateau-politique.js','style.css','i18n/plateau-init.js','i18n/sovarka-partis-resources.js'],{cwd:root,encoding:'utf8'}),'');});
test('membres : quatre français exacts, neuf langues, réutilisation de Membres et catalogue chargé',()=>{const c={};c.window=c;vm.createContext(c);for(const file of ['i18n/resources.js','i18n/sovarka-partis-resources.js','i18n/organization-members-resources.js'])vm.runInContext(read(file),c);const rows=JSON.parse(read('outils/audits/I18N-MEMBRES-ORGANISATIONS-871-sources.json')).rows;assert.equal(rows.length,4);assert.deepEqual(JSON.parse(JSON.stringify(c.RP_I18N_RESOURCES.fr.translation.organizationMembers)),Object.fromEntries(rows));assert.equal(c.RP_I18N_RESOURCES.fr.translation.sovarkaPartis.secMembers,'Membres');for(const [lang,r]of Object.entries(c.RP_I18N_RESOURCES)){assert.equal(Object.keys(r.translation.organizationMembers).length,4);for(const [key,fr]of rows){const text=r.translation.organizationMembers[key];assert.ok(text.trim());if(lang!=='fr')assert.notEqual(text,fr);}assert.ok(r.translation.sovarkaPartis.secMembers);}assert.ok(read('plateau.html').indexOf('organization-members-resources.js')<read('plateau.html').indexOf('i18n/plateau-init.js'));});
